  ('Saka Kuşu romanındaki çalınan küçük tablonun ressamı kimdir?', 'Who painted the small stolen painting in the novel The Goldfinch?', '["Carel Fabritius","Johannes Vermeer","Rembrandt van Rijn","Frans Hals"]'::jsonb),
  ('Benim Olağanüstü Akıllı Arkadaşım''daki Lila''nın resmî adı hangisidir?', 'What is Lila''s formal name in My Brilliant Friend?', '["Raffaella Cerullo","Elena Greco","Carmela Peluso","Gigliola Spagnuolo"]'::jsonb),
  ('Gülün Adı''nda yasak kitabın sayfalarına zehir süren kişi kimdir?', 'Who poisons the forbidden book''s pages in The Name of the Rose?', '["Jorge of Burgos","Malachi of Hildesheim","William of Baskerville","Adso of Melk"]'::jsonb)
  ) v(soru, en_soru, en_secenekler)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

